Q: How to add clickable button for code section in for Markdown on Android Compose? A: <p>I've implemented the `AstBlockNodeComposer`:</p>
<pre><code>class CodeAstBlockComposer(
    private val copyCallback: (String) -&gt; Unit,
    private val useCallback: (String) -&gt; Unit,
) : AstBlockNodeComposer {
    val code = mutableListOf&lt;String&gt;()

    @Composable
    override fun RichTextScope.Compose(
        astNode: AstNode,
        visitChildren: @Composable ((AstNode) -&gt; Unit)
    ) {
        val literal: String = when (astNode.type) {
            is AstIndentedCodeBlock -&gt; (astNode.type as AstIndentedCodeBlock).literal.trim()
            is AstFencedCodeBlock   -&gt; (astNode.type as AstFencedCodeBlock).literal.trim()
            else -&gt; &quot;&quot;
        }

        visitChildren(astNode)

        Column(
            verticalArrangement = Arrangement.spacedBy(4.dp),
        ) {
            // the code snippet
            CodeBlock(text = literal)

            // the buttons row
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp),
            ) {
                // Copy
                Button(onClick = { copyCallback(literal) }) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                    ) {
                        Icon(
                            Icons.Outlined.FileCopy,
                            contentDescription = null)
                        Text(
                            text = stringResource(R.string.copy),
                            color = MaterialTheme.colorScheme.onPrimary,
                            style = MaterialTheme.typography.titleMedium)
                    }
                }

                Spacer(modifier = Modifier.width(4.0.dp))

                // Use
                Button(onClick = { useCallback(literal) }) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                    ) {
                        Icon(
                            Icons.Outlined.Code,
                            contentDescription = null)
                        Text(
                            text = stringResource(R.string.use),
                            color = MaterialTheme.colorScheme.onPrimary,
                            style = MaterialTheme.typography.titleMedium)
                    }
                }
            }
        }
    }

    override fun predicate(astBlockNodeType: AstBlockNodeType): Boolean {
        return astBlockNodeType is AstIndentedCodeBlock ||
               astBlockNodeType is AstFencedCodeBlock
    }
}

</code></pre>
<p>and used it for `MarkdownText`:</p>
<pre><code>Markdown(
  content = text,
  astBlockNodeComposer = CodeAstBlockComposer(
    copyCallback = copyCodeCallback,
    useCallback = useCodeCallback
))
</code></pre>
